define([],function(){let initialised=false;let activeModal=null;let activeTrigger=null;const getBackdrop=function(modal){return document.querySelector('[data-bookflow-modal-backdrop="'+modal.id+'"]')};const hideModal=function(modal){if(!modal){return}modal.classList.remove("show");modal.style.display="none";modal.setAttribute("aria-hidden","true");modal.removeAttribute("aria-modal");const backdrop=getBackdrop(modal);if(backdrop){backdrop.remove()}document.body.classList.remove("modal-open");if(activeModal===modal){activeModal=null;if(activeTrigger){activeTrigger.focus()}activeTrigger=null}};const showModal=function(modal,trigger){if(!modal){return false}activeModal=modal;activeTrigger=trigger;modal.style.display="block";modal.removeAttribute("aria-hidden");modal.setAttribute("aria-modal","true");modal.classList.add("show");document.body.classList.add("modal-open");if(!getBackdrop(modal)){const backdrop=document.createElement("div");backdrop.className="modal-backdrop fade show";backdrop.setAttribute("data-bookflow-modal-backdrop",modal.id);backdrop.addEventListener("click",function(){hideModal(modal)});document.body.appendChild(backdrop)}const firstLink=modal.querySelector(".modal-body a");if(firstLink){firstLink.focus()}return true};const init=function(){if(initialised){return}initialised=true;document.addEventListener("click",function(event){const trigger=event.target.closest('[data-action="bookflow-add-content"]');if(trigger){const modalId=trigger.getAttribute("data-modal-id");const modal=modalId?document.getElementById(modalId):null;if(modal&&showModal(modal,trigger)){event.preventDefault()}return}const close=event.target.closest('[data-action="bookflow-close-add-content"]');if(close){event.preventDefault();hideModal(close.closest(".modal"))}});document.addEventListener("keydown",function(event){if(event.key==="Escape"&&activeModal){event.preventDefault();hideModal(activeModal)}})};return{init:init}});